    23	extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    24	  // Input less than 10mb
    25	  if (size > 10000000) {
    26	    return 0;
    27	  }
    28	
    29	  LibRaw lib_raw;
    30	
    31	  int result = lib_raw.open_buffer(
    32	      const_cast<char*>(reinterpret_cast<const char*>(data)), size);
    33	  if (result != LIBRAW_SUCCESS) {
    34	    return 0;
    35	  }
    36	
    37	  result = lib_raw.unpack();
    38	  if (result != LIBRAW_SUCCESS) {
    39	    return 0;
    40	  }
    41	
    42	  result = lib_raw.dcraw_process();
    43	  if (result != LIBRAW_SUCCESS) {
    44	    return 0;
    45	  }
    46	
    47	  return 0;
    48	}
